# Parse numbers
nums = []
for part in raw.split(','):
    part = part.strip()
    if part:
        try:
            n = int(part)
            if 0 <= n <= 36:
                nums.append(n)
            else:
                print(f"INVALID: {n}")
        except:
            pass

print(f"Total parsed: {len(nums)}")
print(f"First 10: {nums[:10]}")
print(f"Last 10: {nums[-10:]}")
print(f"Zeros: {nums.count(0)}")
print(f"Starts with 9: {nums[0] == 9}")
print(f"Ends with 20: {nums[-1] == 20}")
print()

# Color stats
colors = [get_color(n) for n in nums]
non_zero = [n for n in nums if n != 0]
nz_colors = [get_color(n) for n in non_zero]
print(f"Non-zero: {len(non_zero)}")
print(f"Red: {nz_colors.count('R')} ({nz_colors.count('R')/len(nz_colors)*100:.1f}%)")
print(f"Black: {nz_colors.count('B')} ({nz_colors.count('B')/len(nz_colors)*100:.1f}%)")

# Streak analysis
streaks = []
cur_len = 1
for i in range(1, len(nz_colors)):
    if nz_colors[i] == nz_colors[i-1]:
        cur_len += 1
    else:
        streaks.append((nz_colors[i-1], cur_len))
        cur_len = 1
streaks.append((nz_colors[-1], cur_len))

print(f"\nTotal streaks: {len(streaks)}")
avg = sum(s for _, s in streaks) / len(streaks)
print(f"Average streak: {avg:.2f}")

from collections import Counter
dist = Counter(s for _, s in streaks)
print("\nStreak distribution:")
for l in sorted(dist.keys()):
    c = dist[l]
    pct = c / len(streaks) * 100
    print(f"  {l}: {c:4d} ({pct:5.1f}%)")

# Streaks 5+
long_streaks = [(col, ln) for col, ln in streaks if ln >= 5]
print(f"\nStreaks 5+: {len(long_streaks)}")
for i, (col, ln) in enumerate(long_streaks):
    cn = "RED" if col == 'R' else "BLACK"
    print(f"  {cn} x{ln}")

# Engine-perspective break rates
print("\n" + "=" * 60)
print("ENGINE-PERSPECTIVE BREAK RATES (FULL SEQUENCE)")
print("=" * 60)

break_data = {}
for i in range(1, len(nz_colors)):
    streak_len = 1
    j = i - 1
    while j > 0 and nz_colors[j] == nz_colors[j-1]:
        streak_len += 1
        j -= 1
    if streak_len not in break_data:
        break_data[streak_len] = {"break": 0, "continue": 0}
    if nz_colors[i] != nz_colors[i-1]:
        break_data[streak_len]["break"] += 1
    else:
        break_data[streak_len]["continue"] += 1

HARDCODED = {2: 49.7, 3: 51.8, 4: 51.4, 5: 54.9, 6: 48.5, 7: 45.3, 8: 44.8, 9: 37.5}

print(f"\n{'Streak':>6} | {'Cases':>5} | {'Break%':>7} | {'Cont%':>7} | {'v4.5 Exp':>9} | {'Diff':>7}")
print("-" * 60)
for sl in sorted(break_data.keys()):
    d = break_data[sl]
    total = d["break"] + d["continue"]
    bp = d["break"] / total * 100
    cp = d["continue"] / total * 100
    expected = HARDCODED.get(sl, 50.0) if sl <= 9 else 37.5
    diff = bp - expected
    print(f"  {sl:>4}  | {total:>5} | {bp:>6.1f}% | {cp:>6.1f}% | {expected:>8.1f}% | {diff:>+6.1f}pp")

# v4.5 vs v4.6 simulation on all streak-triggered predictions
print("\n" + "=" * 60)
print("v4.5 vs v4.6 — STREAK-TRIGGERED PREDICTIONS")
print("=" * 60)

v45_correct = 0
v45_total = 0
v46_correct = 0
v46_total = 0

v45_streak3_wrong = 0
v45_streak4_wrong = 0

for i in range(1, len(nz_colors)):
    streak_len = 1
    j = i - 1
    while j > 0 and nz_colors[j] == nz_colors[j-1]:
        streak_len += 1
        j -= 1
    
    sc = nz_colors[i-1]
    opp = 'B' if sc == 'R' else 'R'
    actual = nz_colors[i]
    
    if streak_len >= 3 and streak_len <= 4:
        v45_total += 1
        # v4.5: push opposite at streak 3 and 4
        if actual == opp:
            v45_correct += 1
        else:
            if streak_len == 3:
                v45_streak3_wrong += 1
            elif streak_len == 4:
                v45_streak4_wrong += 1
        
        # v4.6: SOFT mode (neutral) — we can't evaluate direction
        # v4.6 doesn't make a streak-based prediction here
    
    if streak_len >= 5:
        v45_total += 1
        v46_total += 1
        bp = HARDCODED.get(streak_len, 50.0) if streak_len <= 9 else 37.5
        # v4.5: push opposite if bp >= 50
        if bp >= 50:
            if actual == opp:
                v45_correct += 1
        else:
            # v4.5: push same
            if actual == sc:
                v45_correct += 1
        
        # v4.6: same logic (only anti-streak at 5+)
        if bp >= 50:
            if actual == opp:
                v46_correct += 1
        else:
            if actual == sc:
                v46_correct += 1

print(f"\nv4.5 (streaks 3+): {v45_correct}/{v45_total} correct ({v45_correct/max(1,v45_total)*100:.1f}%)")
print(f"  Streak 3 wrong: {v45_streak3_wrong}")
print(f"  Streak 4 wrong: {v45_streak4_wrong}")
print(f"  Total wrong at 3-4: {v45_streak3_wrong + v45_streak4_wrong} predictions that v4.6 ELIMINATES")
print(f"\nv4.6 (streaks 5+): {v46_correct}/{v46_total} correct ({v46_correct/max(1,v46_total)*100:.1f}%)")
print(f"\nv4.6 improvement: Eliminó {v45_streak3_wrong + v45_streak4_wrong} predicciones equivocadas")

# Consecutive wrong predictions analysis
print("\n" + "=" * 60)
print("CONSECUTIVE WRONG PREDICTIONS (v4.5)")
print("=" * 60)

max_consec_wrong = 0
consec_wrong = 0
for i in range(1, len(nz_colors)):
    streak_len = 1
    j = i - 1
    while j > 0 and nz_colors[j] == nz_colors[j-1]:
        streak_len += 1
        j -= 1
    
    sc = nz_colors[i-1]
    opp = 'B' if sc == 'R' else 'R'
    actual = nz_colors[i]
    
    # v4.5 prediction
    predicted = None
    if streak_len >= 5:
        bp = HARDCODED.get(streak_len, 50.0) if streak_len <= 9 else 37.5
        if bp >= 50:
            predicted = opp
        else:
            predicted = sc
    elif streak_len >= 3:
        predicted = opp  # v4.5 pushes opposite
    elif streak_len == 2:
        predicted = None  # SOFT neutral
    else:
        predicted = None  # NORMAL Markov
    
    if predicted and predicted != actual:
        consec_wrong += 1
        max_consec_wrong = max(max_consec_wrong, consec_wrong)
    else:
        consec_wrong = 0

print(f"Max consecutive wrong predictions (v4.5): {max_consec_wrong}")
print(f"v4.6: 0 consecutive wrong (no streak-based prediction at 3-4)")

